files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --focus: #e94560;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 24px;
  border-radius: var(--radius);
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  color: var(--accent);
  margin-bottom: 4px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field label {
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

input[type="range"] {
  width: 100%;
  height: 8px;
  border-radius: 4px;
  background: var(--primary);
  outline: none;
  -webkit-appearance: none;
  appearance: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 2px solid var(--text);
}

input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--accent);
  cursor: pointer;
  border: 2px solid var(--text);
}

input[type="range"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.options {
  border: none;
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  padding: 0;
}

.options label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 1rem;
}

input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
  cursor: pointer;
}

input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 14px 24px;
  font-size: 1.125rem;
  font-weight: 700;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
}

.btn:hover { background: #c73650; }
.btn:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.btn:active { transform: scale(0.98); background: #a82a42; }

.output {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  word-break: break-all;
}

.password {
  font-family: 'Courier New', monospace;
  font-size: 1.125rem;
  color: var(--text);
  min-height: 1.5em;
}

.strength {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 600;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .options { gap: 12px 16px; }
}

const lengthInput = document.getElementById('length');
const lengthValue = document.getElementById('lengthValue');
const uppercaseCheck = document.getElementById('uppercase');
const numbersCheck = document.getElementById('numbers');
const symbolsCheck = document.getElementById('symbols');
const generateBtn = document.getElementById('generate');
const passwordEl = document.getElementById('password');
const strengthEl = document.getElementById('strength');

const LOWER = 'abcdefghijklmnopqrstuvwxyz';
const UPPER = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const NUMBERS = '0123456789';
const SYMBOLS = '!@#$%^&*()_+-=[]{}|;:,.<>?';

lengthInput.addEventListener('input', () => {
  lengthValue.textContent = lengthInput.value;
  lengthInput.setAttribute('aria-valuenow', lengthInput.value);
});

function getRandomInt(max) {
  if (window.crypto && window.crypto.getRandomValues) {
    const array = new Uint32Array(1);
    window.crypto.getRandomValues(array);
    return array[0] % max;
  }
  return Math.floor(Math.random() * max);
}

function generatePassword() {
  const length = parseInt(lengthInput.value, 10);
  let chars = LOWER;
  if (uppercaseCheck.checked) chars += UPPER;
  if (numbersCheck.checked) chars += NUMBERS;
  if (symbolsCheck.checked) chars += SYMBOLS;

  if (chars.length === 0) {
    passwordEl.textContent = 'Select at least one character type';
    strengthEl.textContent = 'Strength: —';
    return;
  }

  let password = '';
  for (let i = 0; i < length; i++) {
    password += chars[getRandomInt(chars.length)];
  }

  passwordEl.textContent = password;
  updateStrength(password, length, chars.length);
}

function updateStrength(password, length, charsetSize) {
  const entropy = length * Math.log2(charsetSize);
  let label = 'Weak';
  if (entropy >= 80) label = 'Strong';
  else if (entropy >= 50) label = 'Medium';
  strengthEl.textContent = `Strength: ${label}`;
}

generateBtn.addEventListener('click', generatePassword);

// Initial generation on load
generatePassword();
